# ! [doc = " Utilities related to FFI bindings."] # ! [doc = ""] # ! [doc = " This module provides utilities to handle data across non-Rust"] # ! [doc = " interfaces, like other programming languages and the underlying"] # ! [doc = " operating system. It is mainly of use for FFI (Foreign Function"] # ! [doc = " Interface) bindings and code that needs to exchange C-like strings"] # ! [doc = " with other languages."] # ! [doc = ""] # ! [doc = " # Overview"] # ! [doc = ""] # ! [doc = " Rust represents owned strings with the [`String`] type, and"] # ! [doc = " borrowed slices of strings with the [`str`] primitive. Both are"] # ! [doc = " always in UTF-8 encoding, and may contain nul bytes in the middle,"] # ! [doc = " i.e., if you look at the bytes that make up the string, there may"] # ! [doc = " be a `\\0` among them. Both `String` and `str` store their length"] # ! [doc = " explicitly; there are no nul terminators at the end of strings"] # ! [doc = " like in C."] # ! [doc = ""] # ! [doc = " C strings are different from Rust strings:"] # ! [doc = ""] # ! [doc = " * **Encodings** - Rust strings are UTF-8, but C strings may use"] # ! [doc = " other encodings. If you are using a string from C, you should"] # ! [doc = " check its encoding explicitly, rather than just assuming that it"] # ! [doc = " is UTF-8 like you can do in Rust."] # ! [doc = ""] # ! [doc = " * **Character size** - C strings may use `char` or `wchar_t`-sized"] # ! [doc = " characters; please **note** that C's `char` is different from Rust's."] # ! [doc = " The C standard leaves the actual sizes of those types open to"] # ! [doc = " interpretation, but defines different APIs for strings made up of"] # ! [doc = " each character type. Rust strings are always UTF-8, so different"] # ! [doc = " Unicode characters will be encoded in a variable number of bytes"] # ! [doc = " each. The Rust type [`char`] represents a '[Unicode scalar"] # ! [doc = " value]', which is similar to, but not the same as, a '[Unicode"] # ! [doc = " code point]'."] # ! [doc = ""] # ! [doc = " * **Nul terminators and implicit string lengths** - Often, C"] # ! [doc = " strings are nul-terminated, i.e., they have a `\\0` character at the"] # ! [doc = " end. The length of a string buffer is not stored, but has to be"] # ! [doc = " calculated; to compute the length of a string, C code must"] # ! [doc = " manually call a function like `strlen()` for `char`-based strings,"] # ! [doc = " or `wcslen()` for `wchar_t`-based ones. Those functions return"] # ! [doc = " the number of characters in the string excluding the nul"] # ! [doc = " terminator, so the buffer length is really `len+1` characters."] # ! [doc = " Rust strings don't have a nul terminator; their length is always"] # ! [doc = " stored and does not need to be calculated. While in Rust"] # ! [doc = " accessing a string's length is an *O*(1) operation (because the"] # ! [doc = " length is stored); in C it is an *O*(*n*) operation because the"] # ! [doc = " length needs to be computed by scanning the string for the nul"] # ! [doc = " terminator."] # ! [doc = ""] # ! [doc = " * **Internal nul characters** - When C strings have a nul"] # ! [doc = " terminator character, this usually means that they cannot have nul"] # ! [doc = " characters in the middle — a nul character would essentially"] # ! [doc = " truncate the string. Rust strings *can* have nul characters in"] # ! [doc = " the middle, because nul does not have to mark the end of the"] # ! [doc = " string in Rust."] # ! [doc = ""] # ! [doc = " # Representations of non-Rust strings"] # ! [doc = ""] # ! [doc = " [`CString`] and [`CStr`] are useful when you need to transfer"] # ! [doc = " UTF-8 strings to and from languages with a C ABI, like Python."] # ! [doc = ""] # ! [doc = " * **From Rust to C:** [`CString`] represents an owned, C-friendly"] # ! [doc = " string: it is nul-terminated, and has no internal nul characters."] # ! [doc = " Rust code can create a [`CString`] out of a normal string (provided"] # ! [doc = " that the string doesn't have nul characters in the middle), and"] # ! [doc = " then use a variety of methods to obtain a raw <code>\\*mut [u8]</code> that can"] # ! [doc = " then be passed as an argument to functions which use the C"] # ! [doc = " conventions for strings."] # ! [doc = ""] # ! [doc = " * **From C to Rust:** [`CStr`] represents a borrowed C string; it"] # ! [doc = " is what you would use to wrap a raw <code>\\*const [u8]</code> that you got from"] # ! [doc = " a C function. A [`CStr`] is guaranteed to be a nul-terminated array"] # ! [doc = " of bytes. Once you have a [`CStr`], you can convert it to a Rust"] # ! [doc = " <code>&[str]</code> if it's valid UTF-8, or lossily convert it by adding"] # ! [doc = " replacement characters."] # ! [doc = ""] # ! [doc = " [`OsString`] and [`OsStr`] are useful when you need to transfer"] # ! [doc = " strings to and from the operating system itself, or when capturing"] # ! [doc = " the output of external commands. Conversions between [`OsString`],"] # ! [doc = " [`OsStr`] and Rust strings work similarly to those for [`CString`]"] # ! [doc = " and [`CStr`]."] # ! [doc = ""] # ! [doc = " * [`OsString`] losslessly represents an owned platform string. However, this"] # ! [doc = " representation is not necessarily in a form native to the platform."] # ! [doc = " In the Rust standard library, various APIs that transfer strings to/from the operating"] # ! [doc = " system use [`OsString`] instead of plain strings. For example,"] # ! [doc = " [`env::var_os()`] is used to query environment variables; it"] # ! [doc = " returns an <code>[Option]<[OsString]></code>. If the environment variable"] # ! [doc = " exists you will get a <code>[Some]\\(os_string)</code>, which you can"] # ! [doc = " *then* try to convert to a Rust string. This yields a [`Result`], so that"] # ! [doc = " your code can detect errors in case the environment variable did"] # ! [doc = " not in fact contain valid Unicode data."] # ! [doc = ""] # ! [doc = " * [`OsStr`] losslessly represents a borrowed reference to a platform string."] # ! [doc = " However, this representation is not necessarily in a form native to the platform."] # ! [doc = " It can be converted into a UTF-8 Rust string slice in a similar way to"] # ! [doc = " [`OsString`]."] # ! [doc = ""] # ! [doc = " # Conversions"] # ! [doc = ""] # ! [doc = " ## On Unix"] # ! [doc = ""] # ! [doc = " On Unix, [`OsStr`] implements the"] # ! [doc = " <code>std::os::unix::ffi::[OsStrExt][unix.OsStrExt]</code> trait, which"] # ! [doc = " augments it with two methods, [`from_bytes`] and [`as_bytes`]."] # ! [doc = " These do inexpensive conversions from and to byte slices."] # ! [doc = ""] # ! [doc = " Additionally, on Unix [`OsString`] implements the"] # ! [doc = " <code>std::os::unix::ffi::[OsStringExt][unix.OsStringExt]</code> trait,"] # ! [doc = " which provides [`from_vec`] and [`into_vec`] methods that consume"] # ! [doc = " their arguments, and take or produce vectors of [`u8`]."] # ! [doc = ""] # ! [doc = " ## On Windows"] # ! [doc = ""] # ! [doc = " An [`OsStr`] can be losslessly converted to a native Windows string. And"] # ! [doc = " a native Windows string can be losslessly converted to an [`OsString`]."] # ! [doc = ""] # ! [doc = " On Windows, [`OsStr`] implements the"] # ! [doc = " <code>std::os::windows::ffi::[OsStrExt][windows.OsStrExt]</code> trait,"] # ! [doc = " which provides an [`encode_wide`] method. This provides an"] # ! [doc = " iterator that can be [`collect`]ed into a vector of [`u16`]. After a nul"] # ! [doc = " characters is appended, this is the same as a native Windows string."] # ! [doc = ""] # ! [doc = " Additionally, on Windows [`OsString`] implements the"] # ! [doc = " <code>std::os::windows:ffi::[OsStringExt][windows.OsStringExt]</code>"] # ! [doc = " trait, which provides a [`from_wide`] method to convert a native Windows"] # ! [doc = " string (without the terminating nul character) to an [`OsString`]."] # ! [doc = ""] # ! [doc = " ## Other platforms"] # ! [doc = ""] # ! [doc = " Many other platforms provide their own extension traits in a"] # ! [doc = " `std::os::*::ffi` module."] # ! [doc = ""] # ! [doc = " ## On all platforms"] # ! [doc = ""] # ! [doc = " On all platforms, [`OsStr`] consists of a sequence of bytes that is encoded as a superset of"] # ! [doc = " UTF-8; see [`OsString`] for more details on its encoding on different platforms."] # ! [doc = ""] # ! [doc = " For limited, inexpensive conversions from and to bytes, see [`OsStr::as_encoded_bytes`] and"] # ! [doc = " [`OsStr::from_encoded_bytes_unchecked`]."] # ! [doc = ""] # ! [doc = " For basic string processing, see [`OsStr::slice_encoded_bytes`]."] # ! [doc = ""] # ! [doc = " [Unicode scalar value]: https://www.unicode.org/glossary/#unicode_scalar_value"] # ! [doc = " [Unicode code point]: https://www.unicode.org/glossary/#code_point"] # ! [doc = " [`env::set_var()`]: crate::env::set_var \"env::set_var\""] # ! [doc = " [`env::var_os()`]: crate::env::var_os \"env::var_os\""] # ! [doc = " [unix.OsStringExt]: crate::os::unix::ffi::OsStringExt \"os::unix::ffi::OsStringExt\""] # ! [doc = " [`from_vec`]: crate::os::unix::ffi::OsStringExt::from_vec \"os::unix::ffi::OsStringExt::from_vec\""] # ! [doc = " [`into_vec`]: crate::os::unix::ffi::OsStringExt::into_vec \"os::unix::ffi::OsStringExt::into_vec\""] # ! [doc = " [unix.OsStrExt]: crate::os::unix::ffi::OsStrExt \"os::unix::ffi::OsStrExt\""] # ! [doc = " [`from_bytes`]: crate::os::unix::ffi::OsStrExt::from_bytes \"os::unix::ffi::OsStrExt::from_bytes\""] # ! [doc = " [`as_bytes`]: crate::os::unix::ffi::OsStrExt::as_bytes \"os::unix::ffi::OsStrExt::as_bytes\""] # ! [doc = " [`OsStrExt`]: crate::os::unix::ffi::OsStrExt \"os::unix::ffi::OsStrExt\""] # ! [doc = " [windows.OsStrExt]: crate::os::windows::ffi::OsStrExt \"os::windows::ffi::OsStrExt\""] # ! [doc = " [`encode_wide`]: crate::os::windows::ffi::OsStrExt::encode_wide \"os::windows::ffi::OsStrExt::encode_wide\""] # ! [doc = " [`collect`]: crate::iter::Iterator::collect \"iter::Iterator::collect\""] # ! [doc = " [windows.OsStringExt]: crate::os::windows::ffi::OsStringExt \"os::windows::ffi::OsStringExt\""] # ! [doc = " [`from_wide`]: crate::os::windows::ffi::OsStringExt::from_wide \"os::windows::ffi::OsStringExt::from_wide\""] # ! [stable (feature = "rust1" , since = "1.0.0")] use split_decls_genesis :: ourprelude :: * ; #[stable (feature = "c_str_module" , since = "1.88.0")] pub mod c_str ; #[stable (feature = "core_c_void" , since = "1.30.0")] pub use core :: ffi :: c_void ; #[unstable (feature = "c_variadic" , reason = "the `c_variadic` feature has not been properly tested on \
              all supported platforms" , issue = "44930")] pub use core :: ffi :: { VaArgSafe , VaList , VaListImpl } ; #[stable (feature = "core_ffi_c" , since = "1.64.0")] pub use core :: ffi :: { c_char , c_double , c_float , c_int , c_long , c_longlong , c_schar , c_short , c_uchar , c_uint , c_ulong , c_ulonglong , c_ushort , } ; #[unstable (feature = "c_size_t" , issue = "88345")] pub use core :: ffi :: { c_ptrdiff_t , c_size_t , c_ssize_t } ; #[doc (inline)] #[stable (feature = "cstr_from_bytes_until_nul" , since = "1.69.0")] pub use self :: c_str :: FromBytesUntilNulError ; #[doc (inline)] #[stable (feature = "cstr_from_bytes" , since = "1.10.0")] pub use self :: c_str :: FromBytesWithNulError ; #[doc (inline)] #[stable (feature = "cstring_from_vec_with_nul" , since = "1.58.0")] pub use self :: c_str :: FromVecWithNulError ; #[doc (inline)] #[stable (feature = "cstring_into" , since = "1.7.0")] pub use self :: c_str :: IntoStringError ; #[doc (inline)] #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: c_str :: NulError ; #[doc (inline)] #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: c_str :: { CStr , CString } ; #[stable (feature = "rust1" , since = "1.0.0")] #[doc (inline)] pub use self :: os_str :: { OsStr , OsString } ; #[stable (feature = "os_str_display" , since = "1.87.0")] pub mod os_str ;